17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.Collections;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.Map;
25	import java.util.Objects;
26	import java.util.stream.Collectors;
27	
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.mapper.OwnerMapper;
32	import org.springframework.samples.petclinic.mapper.PetMapper;
33	import org.springframework.samples.petclinic.mapper.VisitMapper;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
111	        owner.setCity(canonicalCity(owner.getCity()));
112	        if (owner.getRegistrationDate() == null) {
113	            owner.setRegistrationDate(LocalDate.now());
114	        }
115	        if (isDailyRegistrationLimitReached()) {
116	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
117	        }
118	        if (isCityCapacityReached(owner.getCity())) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        int membershipNumber = this.clinicService.findAllOwners().size() + 1;
125	        owner.setMembershipNumber(membershipNumber);
126	        owner.setCustomerCode(customerCode(owner));
127	        owner.setMembershipTier(membershipNumber <= 100 ? "FOUNDING" : "STANDARD");
128	        owner.setNamesakeCount(namesakeCount(owner));
129	        owner.setSharesHousehold(sharesHousehold(owner));
130	        owner.setLocality(locality(owner));
131	        this.clinicService.saveOwner(owner);
132	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
133	        headers.setLocation(UriComponentsBuilder.newInstance()
134	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
135	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
141	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
142	        if (currentOwner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        currentOwner.setAddress(ownerFieldsDto.getAddress());
146	        currentOwner.setCity(ownerFieldsDto.getCity());
147	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
148	        currentOwner.setLastName(ownerFieldsDto.getLastName());
149	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
150	        this.clinicService.saveOwner(currentOwner);
151	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Transactional
156	    @Override
157	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
158	        Owner owner = this.clinicService.findOwnerById(ownerId);
159	        if (owner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        this.clinicService.deleteOwner(owner);
163	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        HttpHeaders headers = new HttpHeaders();
174	        Pet pet = petMapper.toPet(petFieldsDto);
175	        owner.setId(ownerId);
176	        pet.setOwner(owner);
177	        pet.getType().setName(null);
178	        this.clinicService.savePet(pet);
179	        PetDto petDto = petMapper.toPetDto(pet);
180	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
181	            .buildAndExpand(pet.getId()).toUri());
182	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
188	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
189	        if (currentOwner != null) {
190	            Pet currentPet = this.clinicService.findPetById(petId);
191	            if (currentPet != null) {
192	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
193	                currentPet.setName(petFieldsDto.getName());
194	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
195	                this.clinicService.savePet(currentPet);
196	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
197	            }
198	        }
199	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
205	        HttpHeaders headers = new HttpHeaders();
206	        Visit visit = visitMapper.toVisit(visitFieldsDto);
207	        Pet pet = new Pet();
208	        pet.setId(petId);
209	        visit.setPet(pet);
210	        this.clinicService.saveVisit(visit);
211	        VisitDto visitDto = visitMapper.toVisitDto(visit);
212	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
213	            .buildAndExpand(visit.getId()).toUri());
214	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
215	    }
216	
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
221	        Owner owner = this.clinicService.findOwnerById(ownerId);
222	        if (owner != null) {
223	            Pet pet = owner.getPet(petId);
224	            if (pet != null) {
225	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
226	            }
227	        }
228	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
229	    }
230	
231	    /**
232	     * Determines whether an owner conflicting with the given one already exists, i.e. any existing
233	     * owner using the same telephone number.
234	     *
235	     * @param owner the candidate owner to check
236	     * @return {@code true} if another owner already uses the telephone number, {@code false} otherwise
237	     */
238	    /**
239	     * Builds the customer code assigned to a newly created owner, formatted as
240	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
241	     * already registered in the same city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
242	     *
243	     * @param owner the owner being created
244	     * @return the customer code for the owner
245	     */
246	    /**
247	     * Counts how many other owners already share the given owner's last name at the moment of
248	     * creation. The owner being created is not yet persisted and so is not included in the count.
249	     *
250	     * @param owner the owner being created
251	     * @return the number of existing owners with the same last name
252	     */
253	    /**
254	     * Determines whether the newly created owner shares a household with an existing owner, i.e.
255	     * whether another owner already has the same address and city. Both values are matched
256	     * case- and whitespace-insensitively.
257	     *
258	     * @param owner the owner being created
259	     * @return {@code true} if another owner already has the same address and city, {@code false} otherwise
260	     */
261	    private boolean sharesHousehold(Owner owner) {
262	        String address = normalize(owner.getAddress());
263	        String city = normalize(owner.getCity());
264	        return this.clinicService.findAllOwners().stream()
265	            .anyMatch(existing -> Objects.equals(address, normalize(existing.getAddress()))
266	                && Objects.equals(city, normalize(existing.getCity())));
267	    }
268	
269	    /**
270	     * Determines the locality of a newly created owner. The owner is {@code "local"} if their city
271	     * is the single most common city among the owners that already exist at the moment of creation
272	     * (i.e. strictly more owners live there than in any other city); otherwise the owner is
273	     * {@code "remote"}. When no owners yet exist, or when several cities are tied for most common,
274	     * the owner is {@code "remote"}. Cities are matched case- and whitespace-insensitively.
275	     *
276	     * @param owner the owner being created
277	     * @return {@code "local"} or {@code "remote"}
278	     */
279	    private String locality(Owner owner) {
280	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
281	            .map(existing -> normalize(existing.getCity()))
282	            .filter(Objects::nonNull)
283	            .collect(Collectors.groupingBy(city -> city, Collectors.counting()));
284	        if (countsByCity.isEmpty()) {
285	            return "remote";
286	        }
287	        long max = Collections.max(countsByCity.values());
288	        List<String> mostCommon = countsByCity.entrySet().stream()
289	            .filter(entry -> entry.getValue() == max)
290	            .map(Map.Entry::getKey)
291	            .toList();
292	        if (mostCommon.size() == 1 && mostCommon.get(0).equals(normalize(owner.getCity()))) {
293	            return "local";
294	        }
295	        return "remote";
296	    }
297	
298	    private int namesakeCount(Owner owner) {
299	        String lastName = owner.getLastName();
300	        return (int) this.clinicService.findAllOwners().stream()
301	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
302	            .count();
303	    }
304	
305	    private String customerCode(Owner owner) {
306	        String city = owner.getCity();
307	        long existingInCity = this.clinicService.findAllOwners().stream()
308	            .filter(existing -> Objects.equals(existing.getCity(), city))
309	            .count();
310	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
311	    }
312	
313	    /**
314	     * Determines the canonical spelling of the city for a newly created owner. If another owner
315	     * already lives in the same city (matched case- and whitespace-insensitively), that owner's exact
316	     * spelling of the city name is reused so that all owners in a city share a consistent value.
317	     * Otherwise the supplied city is title-cased (e.g. {@code "new york"} becomes {@code "New York"}).
318	     *
319	     * @param city the raw city as supplied when creating the owner, may be {@code null}
320	     * @return the canonical city spelling, or {@code null} if {@code city} was {@code null}
321	     */
322	    private String canonicalCity(String city) {
323	        if (city == null) {
324	            return null;
325	        }
326	        String normalized = normalize(city);
327	        for (Owner existing : this.clinicService.findAllOwners()) {
328	            if (existing.getCity() != null && normalized.equals(normalize(existing.getCity()))) {
329	                return existing.getCity();
330	            }
331	        }
332	        return titleCase(city);
333	    }
334	
335	    /**
336	     * Title-cases a value by upper-casing the first letter of every whitespace-separated word and
337	     * lower-casing the rest, collapsing any run of internal whitespace to a single space (e.g.
338	     * {@code "new  YORK city"} becomes {@code "New York City"}).
339	     *
340	     * @param value the value to title-case
341	     * @return the title-cased value
342	     */
343	    private static String titleCase(String value) {
344	        StringBuilder result = new StringBuilder();
345	        for (String word : value.strip().split("\\s+")) {
346	            if (word.isEmpty()) {
347	                continue;
348	            }
349	            if (result.length() > 0) {
350	                result.append(' ');
351	            }
352	            result.append(Character.toUpperCase(word.charAt(0)))
353	                .append(word.substring(1).toLowerCase(Locale.ROOT));
354	        }
355	        return result.toString();
356	    }
357	
358	    /**
359	     * Determines whether the maximum number of owners allowed to be registered on a single day has
360	     * already been reached. At most 20 owners may be created with today's registration date; once
361	     * that many exist, further registrations for today are rejected.
362	     *
363	     * @return {@code true} if 20 or more owners already have today's registration date
364	     */
365	    private boolean isDailyRegistrationLimitReached() {
366	        LocalDate today = LocalDate.now();
367	        long registeredToday = this.clinicService.findAllOwners().stream()
368	            .filter(existing -> today.equals(existing.getRegistrationDate()))
369	            .count();
370	        return registeredToday >= 20;
371	    }
372	
373	    /**
374	     * Determines whether the city of a newly created owner has already reached its capacity. At most
375	     * 8 owners may live in a single city; once a city already contains 8 owners, further registrations
376	     * for that city are rejected. Cities are matched case- and whitespace-insensitively so that
377	     * differing spellings of the same city name count towards the same limit.
378	     *
379	     * @param city the canonical city of the owner being created, may be {@code null}
380	     * @return {@code true} if the city already contains 8 or more owners, {@code false} otherwise
381	     */
382	    private boolean isCityCapacityReached(String city) {
383	        String normalized = normalize(city);
384	        long existingInCity = this.clinicService.findAllOwners().stream()
385	            .filter(existing -> Objects.equals(normalized, normalize(existing.getCity())))
386	            .count();
387	        return existingInCity >= 8;
388	    }
389	
390	    private boolean isDuplicateOwner(Owner owner) {
391	        return this.clinicService.findAllOwners().stream()
392	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
393	    }
394	
395	    /**
396	     * Normalises a telephone number to digits only by stripping spaces, dashes and parentheses (and
397	     * any other non-digit characters). This is applied before storing the number and before the
398	     * telephone-uniqueness check, so that e.g. {@code "(613) 555-0100"} and {@code "6135550100"} are
399	     * stored identically and treated as the same number.
400	     *
401	     * @param telephone the raw telephone number, may be {@code null}
402	     * @return the digits-only telephone number, or {@code null} if {@code telephone} was {@code null}
403	     */
404	    private static String normalizeTelephone(String telephone) {
405	        if (telephone == null) {
406	            return null;
407	        }
408	        return telephone.replaceAll("[^0-9]", "");
409	    }
410	
411	    /**
412	     * Determines whether the given owner's email address is already used by another owner. An owner
413	     * without an email address never conflicts. The comparison is case-insensitive and ignores
414	     * surrounding or repeated whitespace, so e.g. {@code "  John.Smith@Example.com "} and
415	     * {@code "john.smith@example.com"} are treated as the same address.
416	     *
417	     * @param owner the candidate owner to check
418	     * @return {@code true} if another owner already uses the email address, {@code false} otherwise
419	     */
420	    private boolean isDuplicateEmail(Owner owner) {
421	        String email = normalize(owner.getEmail());
422	        if (email == null || email.isEmpty()) {
423	            return false;
424	        }
425	        return this.clinicService.findAllOwners().stream()
426	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
427	    }
428	
429	    /**
430	     * Normalises a value for case- and whitespace-insensitive duplicate detection: surrounding
431	     * whitespace is stripped, any run of internal whitespace is collapsed to a single space and all
432	     * letters are lower-cased. This is what makes {@code "  john   smith "} and {@code "John Smith"}
433	     * count as the same person (or, for e-mail, the same address) when detecting duplicates.
434	     *
435	     * @param value the raw value, may be {@code null}
436	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
437	     */
438	    private static String normalize(String value) {
439	        if (value == null) {
440	            return null;
441	        }
442	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
443	    }
444	}
